const raw = $('Recibir Datos').first().json;
const d = raw.telefono != null ? raw : JSON.parse(raw.query || '{}');
const valido = v => v != null && String(v).trim() !== '' && String(v) !== 'undefined' && String(v) !== 'null';
const telefono = valido(d.telefono) ? String(d.telefono).trim() : null;
if (!telefono) return [{ json: { resultado: 'ERROR: no se recibió un teléfono válido. Revisá que el mensaje incluye [TELEFONO].' } }];

// Normaliza teléfonos argentinos: quita el 54 del principio y el 9 de celular
// Permite comparar 5492494621486, 2494621486, 492494621486, etc.
const normTel = t => {
  let s = String(t).replace(/\D/g, '');
  if (s.startsWith('54')) s = s.slice(2);
  if (s.startsWith('9') && s.length >= 10) s = s.slice(1);
  return s;
};
const telNorm = normTel(telefono);

const hoy = new Date().toISOString().split('T')[0];

const pacientes = $('Leer Pacientes').all();
const paciente = pacientes.find(i => normTel(i.json.telefono) === telNorm)?.json || {};

const turnos = $('Leer Turnos').all();
const busyStates = ['PENDIENTE','CONFIRMADO','RECORDATORIO_ENVIADO'];

const turnoActivo = turnos
  .filter(i => normTel(i.json.telefono) === telNorm && busyStates.includes(i.json.estado_turno) && i.json.fecha >= hoy)
  .sort((a,b) => a.json.fecha > b.json.fecha ? 1 : -1)[0]?.json || null;

const ocupadosPorFecha = {};
turnos.forEach(t => {
  if (busyStates.includes(t.json.estado_turno)) {
    if (!ocupadosPorFecha[t.json.fecha]) ocupadosPorFecha[t.json.fecha] = 0;
    ocupadosPorFecha[t.json.fecha]++;
  }
});

const diasDisponibles = [];
for (let offset = 1; offset <= 14; offset++) {
  const dt = new Date();
  dt.setDate(dt.getDate() + offset);
  const dow = dt.getDay();
  if (dow === 0) continue;
  const fechaStr = dt.toISOString().split('T')[0];
  const endMin = dow === 6 ? 780 : 1260;
  const maxSlots = Math.floor((endMin - 480) / 45);
  const ocupados = ocupadosPorFecha[fechaStr] || 0;
  if (ocupados < maxSlots) {
    const dias = ['dom','lun','mar','mié','jue','vie','sáb'];
    diasDisponibles.push(`${dias[dow]} ${fechaStr.slice(8)}/${fechaStr.slice(5,7)} (${fechaStr})`);
  }
}

let resultado = `Paciente: ${paciente.nombre || 'No registrado'} | Estado: ${paciente.estado || 'NUEVO'}\n`;
resultado += turnoActivo
  ? `Turno activo: ${turnoActivo.fecha} a las ${turnoActivo.hora} (${turnoActivo.servicio || 'Consulta'})\n`
  : 'Sin turno activo\n';
resultado += diasDisponibles.length > 0
  ? 'Días con disponibilidad próximos 7 días: ' + diasDisponibles.join(', ')
  : 'Sin disponibilidad en los próximos 7 días';

return [{ json: { resultado } }];
